mapper.update:
UPDATE tb_goods_receipt_item i JOIN tb_goods_receipt r ON r.goods_receipt_id=i.goods_receipt_id
   SET i.ingredient_id=#{ingredient_id,jdbcType=VARCHAR},i.base_unit=#{base_unit},i.base_received_qty=i.received_qty*#{per_unit}
 WHERE r.account_id=#{account_id} AND r.status IN ('HISTORY','UNMATCHED') AND i.inventory_movement_id IS NULL
   AND i.supplier_product_id=#{supplier_product_id}
   AND i.ingredient_id IS NULL
